#ifndef OUI_REGISTRY_H
#define OUI_REGISTRY_H

#include <stddef.h>
#include <stdint.h>

// Optional IEEE MA-L registry on the SD card. The file is generated by
// tools/build_oui_registry.py and searched in place; it is never loaded into RAM.
// Returns false when the card/file is absent, malformed, or has no match.
bool ouiRegistryLookup(const uint8_t mac[6], char *name, size_t nameSize);

#endif
